function parseTimeoutMs(value) {
  if (typeof value === "number") {
    return Math.round(value * 1000);
  }
  const match = String(value).trim().match(/^(\d+(?:\.\d+)?)\s*(ms|s|m)?$/);
  const amount = parseFloat(match[1]);
  const unit = match[2] === undefined ? "s" : match[2];
  if (unit === "ms") return Math.round(amount);
  if (unit === "m") return Math.round(amount * 60 * 1000);
  return Math.round(amount * 1000);
}

function parseEndpoint(endpoint) {
  const colonIndex = endpoint.lastIndexOf(":");
  if (colonIndex === -1) {
    return { host: endpoint, port: 443 };
  }
  return {
    host: endpoint.slice(0, colonIndex),
    port: parseInt(endpoint.slice(colonIndex + 1), 10)
  };
}

function parseRetries(value) {
  if (value === undefined || value === null) return 0;
  return parseInt(value, 10);
}

function parseTags(value) {
  let raw = [];
  if (Array.isArray(value)) {
    raw = value;
  } else if (typeof value === "string" && value.trim() !== "") {
    raw = value.split(",");
  }
  const seen = {};
  const tags = [];
  for (const item of raw) {
    const tag = String(item).trim().toLowerCase();
    if (tag === "" || seen[tag]) continue;
    seen[tag] = true;
    tags.push(tag);
  }
  tags.sort();
  return tags;
}

function parseEnabled(value) {
  if (typeof value === "string") value = value.trim().toLowerCase();
  return value === "yes" || value === "true" || value === "on" || value === 1 || value === true;
}

const v1Configs = tool("configs", {});

const notes = [];
for (const config of v1Configs) {
  notes.push(config.owner_note);
}
const priorities = tool("judge_priorities", { notes: notes });

const v2Configs = [];
for (let i = 0; i < v1Configs.length; i++) {
  const v1 = v1Configs[i];
  const endpoint = parseEndpoint(v1.endpoint);
  v2Configs.push({
    name: v1.name,
    timeoutMs: parseTimeoutMs(v1.timeout),
    host: endpoint.host,
    port: endpoint.port,
    retries: parseRetries(v1.retries),
    tags: parseTags(v1.tags),
    enabled: parseEnabled(v1.enabled),
    priority: priorities[i]
  });
}

v2Configs

function parseTimeoutMs(value) {
  if (typeof value === "number") {
    if (!isFinite(value)) return 0;
    return Math.round(value * 1000);
  }
  const s = String(value == null ? "" : value).trim();
  const m = s.match(/^(\d+(?:\.\d+)?)\s*(ms|s|m)?$/i);
  if (!m) return 0;
  const n = parseFloat(m[1]);
  const unit = m[2] ? m[2].toLowerCase() : "s";
  if (unit === "ms") return Math.round(n);
  if (unit === "m") return Math.round(n * 60 * 1000);
  return Math.round(n * 1000);
}

function parseEndpoint(value) {
  const s = String(value == null ? "" : value).trim();
  const idx = s.lastIndexOf(":");
  if (idx !== -1) {
    const portStr = s.slice(idx + 1);
    if (/^\d+$/.test(portStr)) {
      return { host: s.slice(0, idx), port: parseInt(portStr, 10) };
    }
  }
  return { host: s, port: 443 };
}

function parseRetries(value) {
  if (value === undefined || value === null || value === "") return 0;
  const n = typeof value === "number" ? value : Number(String(value).trim());
  if (!isFinite(n)) return 0;
  return Math.round(n);
}

function parseTags(value) {
  const raw = [];
  if (Array.isArray(value)) {
    for (const t of value) raw.push(String(t));
  } else if (typeof value === "string") {
    for (const t of value.split(",")) raw.push(t);
  }
  const seen = {};
  const tags = [];
  for (const t of raw) {
    const clean = t.trim().toLowerCase();
    if (clean === "" || seen[clean]) continue;
    seen[clean] = true;
    tags.push(clean);
  }
  tags.sort();
  return tags;
}

function parseEnabled(value) {
  if (value === true || value === 1) return true;
  if (value === false || value === 0) return false;
  const s = String(value == null ? "" : value).trim().toLowerCase();
  return s === "yes" || s === "true" || s === "on";
}

const v1Configs = tool("configs", {});

const notes = [];
for (const c of v1Configs) {
  notes.push(c.owner_note == null ? "" : String(c.owner_note));
}

const priorities = tool("judge_priorities", { notes: notes });

const v2Configs = [];
let index = 0;
for (const c of v1Configs) {
  const endpoint = parseEndpoint(c.endpoint);
  const priority = priorities[index];
  v2Configs.push({
    name: c.name,
    timeoutMs: parseTimeoutMs(c.timeout),
    host: endpoint.host,
    port: endpoint.port,
    retries: parseRetries(c.retries),
    tags: parseTags(c.tags),
    enabled: parseEnabled(c.enabled),
    priority: priority === "urgent" || priority === "low" ? priority : "normal"
  });
  index += 1;
}

v2Configs

const v1 = tool("configs", {});

const notes = [];
for (const c of v1) {
  notes.push(c.owner_note == null ? "" : c.owner_note);
}
const priorities = tool("judge_priorities", { notes });

const out = [];
let i = 0;
for (const c of v1) {
  // timeout -> timeoutMs
  let t = c.timeout;
  let timeoutMs;
  if (typeof t === "number") {
    timeoutMs = Math.round(t * 1000);
  } else {
    const s = String(t).trim();
    if (/ms$/i.test(s)) {
      timeoutMs = parseInt(s, 10);
    } else if (/s$/i.test(s)) {
      timeoutMs = Math.round(parseFloat(s) * 1000);
    } else if (/m$/i.test(s)) {
      timeoutMs = Math.round(parseFloat(s) * 60 * 1000);
    } else {
      timeoutMs = Math.round(parseFloat(s) * 1000);
    }
  }

  // endpoint -> host, port
  const ep = String(c.endpoint);
  let host = ep;
  let port = 443;
  const parts = ep.split(":");
  if (parts.length === 2 && parts[0] !== "" && /^\d+$/.test(parts[1])) {
    host = parts[0];
    port = parseInt(parts[1], 10);
  }

  // retries
  let retries = 0;
  if (c.retries !== undefined && c.retries !== null && c.retries !== "") {
    retries = parseInt(c.retries, 10);
    if (isNaN(retries)) retries = 0;
  }

  // tags
  let rawTags = [];
  if (Array.isArray(c.tags)) {
    rawTags = c.tags;
  } else if (typeof c.tags === "string" && c.tags.length > 0) {
    rawTags = c.tags.split(",");
  }
  const seen = {};
  const tags = [];
  for (const tg of rawTags) {
    const v = String(tg).trim().toLowerCase();
    if (v === "" || seen[v]) continue;
    seen[v] = true;
    tags.push(v);
  }
  tags.sort();

  // enabled
  let e = c.enabled;
  if (typeof e === "string") e = e.trim().toLowerCase();
  const enabled = e === "yes" || e === "true" || e === "on" || e === 1 || e === true;

  out.push({
    name: c.name,
    timeoutMs: timeoutMs,
    host: host,
    port: port,
    retries: retries,
    tags: tags,
    enabled: enabled,
    priority: priorities[i]
  });
  i++;
}

out;
